package com.sirithree.shopops.admin.benchmark.v1.dataset.stage5;
import static org.assertj.core.api.Assertions.assertThat; import java.util.Map; import org.junit.jupiter.api.Test;
class IdempotencyCandidateFeasibilityTest { @Test void rejectedCandidatesAndFormalDriverGapRemainVisible() throws Exception { Map<String,Object> blueprints=Stage5IdempotencyDatasetSupport.resource("/benchmark/v1/idempotency/stage5/idempotency-scenario-blueprints.json"); assertThat(((Number)blueprints.get("proposedCount")).intValue()).isEqualTo(14); Map<String,Object> review=Stage5IdempotencyDatasetSupport.resource("/benchmark/v1/idempotency/stage5/idempotency-review.json"); @SuppressWarnings("unchecked") Map<String,Object> gap=(Map<String,Object>)review.get("benchmarkDriverGap"); assertThat(gap.get("code")).isEqualTo("IDEMPOTENCY_BENCHMARK_DRIVER_GAP"); }}
